# qx_choice_weighted :: (['a', 'b', 'c'], [1, 2, 3])
import random
def qx_choice_weighted(items, weights):
    return random.choices(items, weights=weights, k=1)[0]

if __name__ == '__main__':
    print(qx_choice_weighted((['a', 'b', 'c'], [1, 2, 3])))

